// Calculate personalized discount based on LTV
const ltv = $node["Calculate Customer LTV"].json["lifetime_value"] || 0;
const orderCount = $node["Calculate Customer LTV"].json["order_count"] || 0;
const customer = $node["Find Birthday Customers"].json;

// Discount tiers based on lifetime value
let discountPercent = 10; // Default
let couponCode = `ANIVER${customer.id}`;
let validDays = 7;

if (ltv >= 2000) {
  discountPercent = 25;
  couponCode = `VIP${customer.id}`;
  validDays = 30;
} else if (ltv >= 1000) {
  discountPercent = 20;
  couponCode = `GOLD${customer.id}`;
  validDays = 15;
} else if (ltv >= 500) {
  discountPercent = 15;
  couponCode = `PLUS${customer.id}`;
  validDays = 10;
}

// Calculate customer's age
const birthYear = new Date(customer.birth_date).getFullYear();
const currentYear = new Date().getFullYear();
const age = currentYear - birthYear;

// Personalized message based on segments
const messages = {
  vip: {
    subject: `Feliz Aniversário ${customer.name}! 🎉 25% OFF Especial`,
    greeting: `Parabéns pelos ${age} anos, nosso cliente VIP!`,
    offer: `Como agradecimento pela sua fidelidade, oferecemos 25% OFF em toda loja!`
  },
  gold: {
    subject: `Feliz Aniversário ${customer.name}! 🎂 20% OFF Especial`,
    greeting: `Feliz ${age} anos, nosso cliente Gold!`,
    offer: `Para celebrar seu aniversário, oferecemos 20% OFF em toda loja!`
  },
  plus: {
    subject: `Feliz Aniversário ${customer.name}! 🎈 15% OFF Especial`,
    greeting: `Parabéns pelos ${age} anos!`,
    offer: `Para seu aniversário, oferecemos 15% OFF em toda loja!`
  },
  default: {
    subject: `Feliz Aniversário ${customer.name}! 🎁 10% OFF Especial`,
    greeting: `Feliz ${age} anos!`,
    offer: `Para celebrar seu aniversário, oferecemos 10% OFF em toda loja!`
  }
};

let messageKey = 'default';
if (discountPercent >= 25) messageKey = 'vip';
else if (discountPercent >= 20) messageKey = 'gold';
else if (discountPercent >= 15) messageKey = 'plus';

const message = messages[messageKey];

return {
  customer,
  discountPercent,
  couponCode,
  validDays,
  ltv,
  orderCount,
  age,
  message,
  segment: messageKey.toUpperCase()
};

// Generate personalized birthday email
const data = $node["Calculate Personalized Offer"].json;
const customer = data.customer;
const message = data.message;
const couponCode = data.couponCode;
const discountPercent = data.discountPercent;
const validDays = data.validDays;
const ltv = data.ltv;
const orderCount = data.orderCount;

// Create coupon URL
const couponUrl = `https://getnexo.com.br?coupon=${couponCode}&birthday=true`;

// Personalized product recommendations based on history
const recommendations = [];
if (ltv > 1000) {
  recommendations.push('Nossa linha premium');
} else if (orderCount > 3) {
  recommendations.push('Produtos da sua categoria favorita');
} else {
  recommendations.push('Nossos best-sellers');
}

// Generate HTML email
const emailHtml = `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${message.subject}</title>
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; line-height: 1.6; color: #333; }
    .container { max-width: 600px; margin: 0 auto; background: #fff; }
    .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 40px 20px; text-align: center; }
    .content { padding: 30px 20px; }
    .coupon { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); color: white; padding: 25px; border-radius: 15px; text-align: center; margin: 20px 0; box-shadow: 0 10px 30px rgba(0,0,0,0.1); }
    .coupon-code { font-size: 28px; font-weight: bold; letter-spacing: 3px; margin: 10px 0; }
    .discount { font-size: 18px; margin-bottom: 15px; }
    .cta-button { display: inline-block; background: #28a745; color: white; padding: 15px 30px; text-decoration: none; border-radius: 25px; font-weight: bold; margin: 20px 0; box-shadow: 0 4px 15px rgba(0,0,0,0.2); }
    .footer { background: #f8f9fa; padding: 20px; text-align: center; font-size: 12px; color: #666; }
    .stats { background: #e9ecef; padding: 15px; border-radius: 8px; margin: 20px 0; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>🎉 ${message.greeting}</h1>
      <p>Hoje é um dia especial e queremos celebrar com você!</p>
    </div>

    <div class="content">
      <p>Olá <strong>${customer.name}</strong>,</p>

      <p>${message.offer}</p>

      <div class="stats">
        <p><strong>Seus ${orderCount} pedidos conosco totalizam R$ ${ltv.toFixed(2)} em compras!</strong></p>
        <p>Como forma de agradecimento, criamos uma oferta exclusiva para você.</p>
      </div>

      <div class="coupon">
        <div class="discount">🎁 ${discountPercent}% DE DESCONTO</div>
        <div class="coupon-code">${couponCode}</div>
        <div>Válido por ${validDays} dias</div>
      </div>

      <div style="text-align: center;">
        <a href="${couponUrl}" class="cta-button">Usar Meu Desconto Agora</a>
      </div>

      <p><strong>Sugestões para você:</strong></p>
      <ul>
        ${recommendations.map(rec => `<li>${rec}</li>`).join('')}
      </ul>

      <p>Esperamos que aproveite seu dia especial! 🥳</p>

      <p>Com carinho,<br>
      <strong>Equipe GetNexo</strong></p>
    </div>

    <div class="footer">
      <p>Esta é uma oferta especial de aniversário e não pode ser combinada com outras promoções.</p>
      <p>Cupom válido apenas para compras online • Não acumulável</p>
    </div>
  </div>
</body>
</html>`;

const emailText = `🎉 ${message.greeting}

Olá ${customer.name},

${message.offer}

Seus ${orderCount} pedidos conosco totalizam R$ ${ltv.toFixed(2)}!

🎁 CUPOM ESPECIAL: ${couponCode}
📉 DESCONTO: ${discountPercent}%
⏰ VÁLIDO POR: ${validDays} dias

Use agora: ${couponUrl}

Sugestões: ${recommendations.join(', ')}

Feliz aniversário!
Equipe GetNexo`;

return {
  emailHtml,
  emailText,
  couponUrl,
  recommendations
};
